package net.kdt.pojavlaunch.ui;

import android.content.res.Resources;import android.graphics.*;import android.util.LruCache;import androidx.annotation.Nullable;
import net.kdt.pojavlaunch.R;import net.kdt.pojavlaunch.Tools;import net.kdt.pojavlaunch.value.MinecraftAccount;import java.io.File;

/** UI-only isometric head renderer. Authentication, skin storage and networking remain untouched. */
public final class SkinHead3DRenderer{
 private static final LruCache<String,Bitmap>CACHE=new LruCache<String,Bitmap>(8*1024){@Override protected int sizeOf(String k,Bitmap v){return Math.max(1,v.getByteCount()/1024);}};private static final java.util.concurrent.ConcurrentHashMap<String,Integer>GEN=new java.util.concurrent.ConcurrentHashMap<>();
 private SkinHead3DRenderer(){}
 public static void invalidate(String username){if(username!=null)GEN.merge(username.toLowerCase(java.util.Locale.ROOT),1,(a,b)->a+b);}
 public static @Nullable Bitmap resolve(Resources r,@Nullable MinecraftAccount account){if(account==null||account.username==null)return fallback(r);File full=new File(Tools.DIR_DATA+"/skins/"+account.username+"_skin.png");Bitmap out=renderFile(full,account.username);if(out!=null)return out;Bitmap flat=account.getSkinFace();if(flat==null)flat=MinecraftAccount.getSkinFace(account.username);return flat!=null?flat:fallback(r);}
 public static @Nullable Bitmap resolve(Resources r,String username){if(username==null)return fallback(r);File full=new File(Tools.DIR_DATA+"/skins/"+username+"_skin.png");Bitmap out=renderFile(full,username);if(out!=null)return out;Bitmap flat=MinecraftAccount.getSkinFace(username);return flat!=null?flat:fallback(r);}
 private static Bitmap renderFile(File f,String identity){if(!f.isFile())return null;int generation=GEN.getOrDefault(identity.toLowerCase(java.util.Locale.ROOT),0);String key=f.getAbsolutePath()+":"+f.length()+":"+f.lastModified()+":"+generation;Bitmap cached=CACHE.get(key);if(cached!=null)return cached;Bitmap skin=BitmapFactory.decodeFile(f.getAbsolutePath());if(skin==null)return null;Bitmap out=render(skin);skin.recycle();if(out!=null)CACHE.put(key,out);return out;}
 private static Bitmap fallback(Resources r){Bitmap skin=BitmapFactory.decodeResource(r,R.drawable.ic_steve);if(skin==null)return null;Bitmap out=render(skin);if(out==null)out=MinecraftAccount.extractSkinHead(skin);skin.recycle();return out;}
 public static Bitmap render(Bitmap skin){if(skin==null||skin.getWidth()<48||skin.getHeight()<16)return null;Bitmap out=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);Paint shadow=new Paint(Paint.ANTI_ALIAS_FLAG);shadow.setColor(0x55000000);c.drawOval(new RectF(15,75,82,91),shadow);PointF[]top=q(48,5,84,23,48,41,12,23),front=q(12,23,48,41,48,84,12,66),side=q(48,41,84,23,84,66,48,84);drawFace(c,skin,8,0,top);drawFace(c,skin,8,8,front);drawFace(c,skin,0,8,side);if(skin.getWidth()>=48&&skin.getHeight()>=16){drawFace(c,skin,40,0,expand(top,48,27,1.8f));drawFace(c,skin,40,8,expand(front,30,54,1.4f));drawFace(c,skin,32,8,expand(side,66,54,1.4f));}return out;}
 private static PointF[]q(float...v){return new PointF[]{new PointF(v[0],v[1]),new PointF(v[2],v[3]),new PointF(v[4],v[5]),new PointF(v[6],v[7])};}
 private static PointF[]expand(PointF[]q,float cx,float cy,float amount){PointF[]o=new PointF[4];for(int i=0;i<4;i++){float dx=q[i].x-cx,dy=q[i].y-cy,len=(float)Math.sqrt(dx*dx+dy*dy);o[i]=new PointF(q[i].x+(len==0?0:dx/len*amount),q[i].y+(len==0?0:dy/len*amount));}return o;}
 private static PointF mix(PointF a,PointF b,float t){return new PointF(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t);}private static PointF bilinear(PointF[]q,float u,float v){PointF t=mix(q[0],q[1],u),b=mix(q[3],q[2],u);return mix(t,b,v);}
 private static void drawFace(Canvas c,Bitmap s,int sx,int sy,PointF[]q){Paint p=new Paint();p.setAntiAlias(false);p.setStyle(Paint.Style.FILL);for(int y=0;y<8;y++)for(int x=0;x<8;x++){int color=s.getPixel(sx+x,sy+y);if(Color.alpha(color)==0)continue;p.setColor(color);float u0=x/8f,u1=(x+1)/8f,v0=y/8f,v1=(y+1)/8f;PointF a=bilinear(q,u0,v0),b=bilinear(q,u1,v0),d=bilinear(q,u0,v1),e=bilinear(q,u1,v1);Path path=new Path();path.moveTo(a.x,a.y);path.lineTo(b.x,b.y);path.lineTo(e.x,e.y);path.lineTo(d.x,d.y);path.close();c.drawPath(path,p);}}
}
